      expect(fixture.calls()).toEqual(reconciliationCalls);

      const retried = fixture.run(false);
      expect(retried.status, retried.stderr).toBe(0);
      expect(fixture.calls()).toEqual([
        ...reconciliationCalls,
        ...reconciliationCalls,
        ...(environment === 'staging' ? ['/internal/ops/seed-staging'] : []),
        'deploy:worker',
        'deploy:web',
      ]);
    });
  }
});
