    RETURNS text
    LANGUAGE sql
    IMMUTABLE
    PARALLEL SAFE
    STRICT
    AS $$ SELECT public.unaccent(value) $$
  `);
  await pool.query(`GRANT USAGE ON SCHEMA public TO ${quotedRuntimeRole}`);
  await pool.query(`
    GRANT SELECT, INSERT, UPDATE, DELETE
