text(await tools.exec_command({cmd:`bash <<'SCRIPT'
set -euo pipefail
scratch="$(mktemp -d -t evorto-terraform-evo110)"
trap 'rm -rf "$scratch"' EXIT
git ls-files -z infrastructure/scaleway | tar --null -T - -cf - | tar -xf - -C "$scratch"
export PATH="$(ops/scaleway/install-verification-tools.sh):$PATH"
for root in staging production; do
  dir="$scratch/infrastructure/scaleway/$root"
  mkdir -p "$dir/tests"
  cat >"$dir/tests/staging-cost.tftest.hcl" <<'EOF'
mock_provider "scaleway" {
  mock_data "scaleway_cockpit_preconfigured_alert" {
    defaults = {
      alerts = [
        { preconfigured_rule_id = "c8991f90-facb-436c-b4ab-6aa13822a451" },
        { preconfigured_rule_id = "eb8a941e-698d-47d6-b62d-4b6c13f7b4b7" }
      ]
    }
  }
}

mock_provider "cloudflare" {}

variables {
  project_id                         = "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee"
  deployer_application_id            = "dddddddd-dddd-4ddd-8ddd-dddddddddddd"
  web_application_id                 = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"
  worker_application_id              = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"
  tem_project_id                     = "cccccccc-cccc-4ccc-8ccc-cccccccccccc"
  bucket_suffix                      = "mockevorto"
  alert_email                        = "test@example.com"
  cloudflare_zone_id                 = "00000000000000000000000000000000"
  container_image                    = "rg.fr-par.scw.cloud/mock/evorto:mock"
  schema_database_password           = "REDACTED"
  runtime_database_password          = "REDACTED"
}

run "worker_and_alerts" {
  command = plan
  plan_options {
    target = [
      module.environment.scaleway_container.worker,
      module.environment.scaleway_cockpit_alert_manager.application
    ]
  }
}
EOF
  if [ "$root" = staging ]; then
    export TF_VAR_production_deployer_application_id="ffffffff-ffff-4fff-8fff-ffffffffffff"
  fi
  terraform -chdir="$dir" init -backend=false -input=false -no-color >"$scratch/init.log" 2>&1 || { cat "$scratch/init.log"; exit 1; }
  terraform -chdir="$dir" test -verbose -no-color >"$scratch/test.log" 2>&1 || { cat "$scratch/test.log"; exit 1; }
  printf '%s mocked plan\\n' "$root"
  rg -A 4 'preconfigured_alert_ids.*=|cpu_limit.*=|memory_limit_bytes.*=' "$scratch/test.log"
  rg '^Success!' "$scratch/test.log"
done
SCRIPT`,yield_time_ms:1000,max_output_tokens:2000}));

